-- Batch 2: the 21 "school pair" enchants (damaging school A raises school B, and B raises A).
-- Each enchant spell's placeholder becomes a proc that fires one half's buff; the other half is an existing
-- proc spell made for it (2861xx), linked to the enchant. spell_proc tells both when to fire: on landing a
-- damaging spell or ability of the source school.
DELETE FROM `spell_dbc` WHERE `ID` IN (84589, 84655, 84593, 84629, 84659, 84617, 84581, 84631, 84583, 84585, 84653, 84641, 84619, 84611, 84649, 84625, 84587, 84621, 84623, 84579, 84635);
DELETE FROM `spell_proc` WHERE `SpellId` IN (SELECT `id` FROM `wcme_owned` WHERE `tbl` = 'spell_proc');
